<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Contratos da empresa';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_contracts'.$q);$labels=['draft'=>'Rascunho','active'=>'Ativo','cancelled'=>'Cancelado'];$hidden=function($action)use($esc,$company_contracts_csrf,$request_key,$contract){echo '<input type="hidden" name="action" value="'.$esc($action).'"><input type="hidden" name="company_contracts_csrf" value="'.$esc($company_contracts_csrf).'"><input type="hidden" name="request_key" value="'.$esc($request_key).'">';if($contract)echo '<input type="hidden" name="contract_id" value="'.(int)$contract['id'].'"><input type="hidden" name="revision" value="'.(int)$contract['revision'].'">';}; ?>
<section class="company-settings-card"><h1>Contratos da empresa</h1><?php if($error){ ?><p role="alert" class="alert alert-danger"><?= $esc($error); ?></p><a href="<?= $esc($url()); ?>">Reabrir contratos</a><?php } ?>
<?php if($contract){ ?><h2><?= $esc($contract['name']); ?> — <?= $esc($labels[$contract['status']]); ?></h2><p><?= $contract['number']===null?'Sem numeração (rascunho)':'Contrato '.(int)$contract['number']; ?> · <?= $esc($contract['start_date'].' até '.$contract['due_date']); ?></p><div style="white-space:pre-wrap"><?= $esc($contract['body']); ?></div>
<?php if($contract['number']!==null){$snapshot=json_decode($contract['snapshot_json'],true,32,JSON_THROW_ON_ERROR); ?><p><?= $esc($snapshot['identity']['legal_name'].' → '.$snapshot['client']['name']); ?></p><a href="<?= $esc($url('?contract='.(int)$contract['id'].'&pdf=1')); ?>">Baixar PDF do contrato</a><?php } ?>
<?php if($can_edit&&$contract['status']==='draft'){ ?><h3>Editar rascunho</h3><?= form_open($url());$hidden('update'); ?><input type="hidden" name="contract[client_id]" value="<?= (int)$contract['client_id']; ?>"><?php $values=$contract;$form_id='contract-edit';require APPPATH.'views/admin/companies/contracts_fields.php'; ?><button type="submit">Salvar rascunho</button><?= form_close(); ?><?= form_open($url());$hidden('activate'); ?><p>Ativar registra a numeração e preserva o texto e as identidades atuais. O documento não registra assinatura ou aceite do cliente.</p><button type="submit">Ativar contrato e preservar texto</button><?= form_close(); ?><?php } ?>
<?php if($can_edit&&in_array($contract['status'],['draft','active'],true)){ ?><?= form_open($url());$hidden('cancel'); ?><button type="submit">Cancelar e preservar histórico</button><?= form_close(); ?><?php } ?>
<?php if($can_create){ ?><?= form_open($url());$hidden('copy'); ?><button type="submit">Copiar para novo rascunho</button><?= form_close(); ?><?php } ?><?php } ?>
<?php if($contract){$file_kind='contract';$file_parent=$contract;require APPPATH.'views/admin/companies/operation_files.php';} ?><h2>Lista de contratos</h2><form method="get" action="<?= $esc($url()); ?>"><label for="contracts-search">Buscar pelo nome</label><input id="contracts-search" class="form-control" name="search" maxlength="191"><button type="submit">Buscar contratos</button></form><table class="table"><thead><tr><th>Número</th><th>Nome</th><th>Estado</th><th>Vigência</th></tr></thead><tbody><?php foreach($directory['items'] as $row){ ?><tr><td><?= $row['number']===null?'Rascunho':(int)$row['number']; ?></td><td><a href="<?= $esc($url('?contract='.(int)$row['id'])); ?>"><?= $esc($row['name']); ?></a></td><td><?= $esc($labels[$row['status']]); ?></td><td><?= $esc($row['due_date']); ?></td></tr><?php } ?></tbody></table><?php if($directory['next']!==null){ ?><a href="<?= $esc($url('?after='.$directory['next'])); ?>">Próxima página</a><?php } ?>
<?php if($can_create){ ?><h2>Novo contrato</h2><form method="get" action="<?= $esc($url()); ?>"><label for="contracts-client-search">Buscar cliente por nome ou documento</label><input id="contracts-client-search" class="form-control" name="client_search" maxlength="191"><button type="submit">Buscar clientes</button></form><?= form_open($url());$hidden('create'); ?><label for="contract-client">Cliente autorizado</label><select id="contract-client" name="contract[client_id]" class="form-control" required><option value="">Selecione</option><?php foreach($clients as $client){ ?><option value="<?= (int)$client['userid']; ?>"><?= $esc($client['company']); ?></option><?php } ?></select><?php $values=['name'=>'','body'=>'','start_date'=>date('Y-m-d'),'due_date'=>date('Y-m-d')];$form_id='contract-new';require APPPATH.'views/admin/companies/contracts_fields.php'; ?><button type="submit">Criar rascunho de contrato</button><?= form_close(); ?><?php } ?></section><?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
